            id: entry.id,
            uptime_secs: entry.started_at.elapsed().as_secs(),
            transactions_ingested: entry.tx_count.load(std::sync::atomic::Ordering::Relaxed),
            last_slot: entry.last_slot.load(std::sync::atomic::Ordering::Relaxed),
        })
        .collect();
    Ok(Json(infos))
}

