                ),
                data: None,
            },
        );
        state.export_jobs.write().await.insert(
            new_id,
            ExportJobEntry {
                status: ExportJobStatus {
                    id: new_id,
                    state: JobState::Running,
                    dataset: "hl_fills".to_string(),
