                    record_count: None,
                    message: None,
                    delivered_to: None,
                    delivery_status: None,
                },
                finished_at: None,
                data: None,
            },
        );

        state.prune_stale_export_jobs().await;

        let exports = state.export_jobs.read().await;
        assert!(!exports.contains_key(&old_id));
        assert!(exports.contains_key(&new_id));
    }

