    for r in records {
        buf.push_str(&format!(
            "{},{},{},{},{},{},{},{},{},{},{}\n",
            r.id,
            r.raw_transaction_id
                .map(|u| u.to_string())
                .unwrap_or_default(),
            csv_escape(&r.network),
            csv_escape(&r.account_address),
            csv_escape(&r.native_token),
            r.pre_balance,
            r.post_balance,
            r.delta,
            r.is_fee_payer,
            r.dataset_version_id
                .map(|u| u.to_string())
                .unwrap_or_default(),
